function discover(){const r=getRecord('sugar-circuit');return `
<section class="digital-hero" aria-labelledby="digital-title">
  <div class="digital-copy"><p class="eyebrow red">THE PORTO LISTENING ROOM</p><h1 id="digital-title">Digital vinyl.<br>A record at a time.</h1><p class="digital-intro">Pick a record. Play a side. Explore the artwork and liner notes while the music plays.</p><div class="actions"><button class="primary coral" data-action="play-record" data-id="${r.id}" data-side="0">${playIcon} Play side A</button><a class="secondary" href="#record/${r.id}">Explore the record ↗</a></div><p class="digital-support">Love a record? Buy the vinyl.<br> Digital only is there too.</p></div>
  <a class="digital-feature" href="#record/${r.id}" aria-label="Explore ${r.title} by ${r.artist}"><div class="digital-object"><div class="vinyl-disc" aria-hidden="true"><div class="vinyl-label"><span>porto</span><small>SIDE A</small></div></div><img class="digital-sleeve" src="${asset(r)}" alt="${r.title} record sleeve"></div><div class="featured-caption"><div><span class="eyebrow">ON THE TURNTABLE</span><h2>${r.title}</h2><p>${r.artist} · ${r.genre}</p></div><span class="featured-arrow" aria-hidden="true">↗</span></div></a>
</section>
<section class="record-browser" aria-labelledby="browse-title"><div class="catalog-heading"><div><h2 id="browse-title">Find your next record</h2><p>Open a cover to listen, collect or buy.</p></div><div class="catalog-tools"><label class="search"><span aria-hidden="true">⌕</span><input id="search" type="search" placeholder="Search records or artists" aria-label="Find a record or artist"></label><label class="genre-select"><span class="visually-hidden">Filter by genre</span><select id="genre-filter">${['All',...new Set(records.map(r=>r.genre))].map(v=>`<option value="${v}" ${v===filter?'selected':''}>${v==='All'?'All genres':v}</option>`).join('')}</select></label></div></div><div id="catalog">${catalogResults()}</div></section><p class="legal-note">Fictional artists and releases. Original artwork and openly licensed demo music. <a href="credits.html">Audio credits ↗</a></p>`}
function filteredRecords(){return records.filter(r=>(filter==='All'||r.genre===filter)&&(`${r.title} ${r.artist} ${r.genre} ${r.tracks.flat().join(" ")}`.toLowerCase().includes(query.toLowerCase())))}
function tracks(r,s){return `<ol class="track-list">${r.tracks[s].map((t,i)=>`<li class="track-row ${current.id===r.id&&side===s&&track===i?'current':''}"><span class="num">${i+1}</span><span class="track-title">${t}</span><time>${fmt(duration(r,s,i))}</time><button class="add-next" data-action="queue" data-id="${r.id}" data-side="${s}" data-track="${i}" aria-label="Add ${t}, side ${sideName(s)}, next in queue">+ Next</button></li>`).join('')}</ol>`}
function buyingOptions(r){return `<section class="ownership" aria-label="Buy this record"><div class="buying-intro"><h3>Take the record home.</h3><p>Start with the artist’s vinyl. Or choose a digital copy.</p></div><div class="buying-options"><div class="buy-format vinyl-format"><span class="eyebrow">VINYL FIRST</span><h3>The physical record</h3><p>For your turntable and your shelf.</p><button class="primary" data-action="buy-vinyl" data-id="${r.id}">Buy vinyl ↗</button></div><div class="buy-format"><span class="eyebrow">DIGITAL ONLY</span><h3>${isOwned(r)?'Your digital demo copy':`Digital copy · £${r.price}`}</h3><p>Demo audio downloads and seeking.</p>${isOwned(r)?`<a class="secondary" href="assets/${r.id}-demo.zip" download>Download demo ↓</a>`:`<button class="secondary" data-action="buy-digital" data-id="${r.id}">Digital only · £${r.price}</button>`}</div></div><p class="legal-note">Demo purchase options. No physical stock or connected shop. No payment is taken.</p></section>`}
function detail(r){return `<div class="detail-top"><a href="#discover" class="back">← All records</a><span class="eyebrow">${r.catalog} / ${r.year}</span></div><div class="detail-layout"><div><div class="detail-art"><img src="${asset(r)}" alt="${r.title} record artwork"></div><button class="secondary open-sleeve-button" data-action="open-sleeve" data-id="${r.id}" aria-expanded="${openSleeveId===r.id}" aria-controls="sleeve-display">${openSleeveId===r.id?'Close':'Open'} sleeve & liner notes</button></div><div class="detail-content"><p class="eyebrow red">DIGITAL VINYL · ${r.genre}</p><h1>${r.title}</h1><p class="artist"><a class="artist-profile-link" href="#artist/${artistForRecord(r)}">${r.artist} ↗</a></p><p class="record-description">${r.description}</p><div class="side-tabs" role="group" aria-label="Choose record side">${[0,1].map(s=>`<button data-action="side" data-side="${s}" class="${selectedSide===s?'active':''}" aria-pressed="${selectedSide===s}">Side ${sideName(s)}</button>`).join('')}</div><div class="actions"><button class="primary coral" data-action="play-record" data-id="${r.id}" data-side="${selectedSide}">${playIcon} Play side ${sideName(selectedSide)}</button>${saveButton(r)}</div>${tracks(r,selectedSide)}<p class="listener-note">A side plays in order. “+ Next” adds a track after the one playing.</p>${buyingOptions(r)}</div></div><div id="sleeve-display">${openSleeveId===r.id?openJacket(r):''}</div><section class="record-story"><h3>Behind the record</h3><div><p>${r.story}</p>${audioCredit(r)}</div></section>`}
function shelf(){let list=records.filter(r=>(saved.includes(r.id)||isOwned(r))&&(shelfFilter!=='Owned copies'||isOwned(r))&&(shelfFilter!=='Saved records'||saved.includes(r.id)));return `<div class="section-head"><div><p class="eyebrow red">A PLACE FOR YOUR RECORDS</p><h1>Your collection.</h1></div><span class="muted">${list.length} ${list.length===1?'record':'records'}</span></div><div class="shelf-tabs">${['All records','Saved records','Owned copies'].map(v=>`<button class="filter ${v===shelfFilter?'active':''}" data-action="shelf-filter" data-filter="${v}" aria-pressed="${v===shelfFilter}">${v}</button>`).join('')}</div>${list.length?vinylShelf(list):`<div class="empty"><h2>A good record stays with you.</h2><p>Add a record from Discover or the player to start your collection.</p><a class="primary" href="#discover">Explore the records ↗</a></div>`}<p class="legal-note">${storageAvailable?'Your collection is saved on this browser and device. No account needed.':'Browser storage is unavailable. Your collection lasts for this visit only.'}</p>`}
function listening(){return `<div class="detail-top"><a class="back" href="#record/${current.id}">← Back to the record</a><span class="eyebrow red">SIDE ${sideName(side)} / ${isOwned(current)?'DIGITAL DEMO COPY':'DIGITAL VINYL'}</span></div><div class="listening-layout"><div class="listening-art"><img src="${asset(current)}" alt="${current.title} record artwork"></div><div class="listening-info"><p class="eyebrow red" id="listening-state">${playing?'NOW PLAYING':'TAKE YOUR TIME'}</p><h1 id="listening-title">${current.tracks[side][track]}</h1><p class="artist"><a class="artist-profile-link" href="#artist/${artistForRecord(current)}">${current.artist} ↗</a></p><p class="muted" style="font-size:13px;margin-top:8px">${current.title} · ${current.year}</p><div class="actions listening-primary-actions"><button class="primary" data-action="toggle" id="focus-play">${playing?pauseIcon:playIcon} ${playing?'Pause':'Play'}</button>${saveButton(current)}<button class="text-button" data-action="lift">↥ Restart side</button></div><div class="session-bars" aria-hidden="true">${Array.from({length:42},(_,i)=>`<i style="height:${8+(i*17%21)}px;animation-delay:${i*.037}s"></i>`).join('')}</div>${tracks(current,side)}${audioCredit(current)}${isOwned(current)?`<label class="listener-note" for="seek">Navigate your demo copy</label><input class="seek" id="seek" aria-label="Seek within current track" type="range" min="0" max="${duration(current,side,track)}" step=".1" value="${audio.currentTime}">`:`<p class="listener-note">Add any track next. Your queue takes priority when the current track ends.</p>`}<button class="text-button" data-action="flip" style="margin-top:15px;font-size:13px">Flip to side ${sideName(1-side)} ↗</button></div></div>`}
function support(){return typeof PortoOctober!=='undefined'?PortoOctober.view('budget'):'<h1>Listening budget</h1><p>Pay for listening. No subscription. Proposed original / variation shares are 90% / 70% to rights holders.</p>'}
function render(){const route=location.hash.slice(1)||'feed';const view=route.split('/')[0];$('#view-title').textContent={discover:'Records',shelf:'My collection',record:'The record',listening:'Listening',support:'Your support',artists:'Artists',artist:'Artist profile'}[view]||({search:'Search',home:'Feed',feed:'Feed',original:'Original',studio:'Your version',variation:'Your version',you:'Your space',creator:'Creator',budget:'Listening budget',ledger:'Porto Ledger'}[view]||'Home');document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===view||(view==='home'&&a.dataset.nav==='feed')||(view==='record'&&a.dataset.nav==='discover')||(view==='artist'&&a.dataset.nav==='artists')||(['variation','studio'].includes(view)&&a.dataset.nav==='studio')||(['creator','you'].includes(view)&&a.dataset.nav==='feed')));const october=typeof PortoOctober!=='undefined'?PortoOctober.view(route):null;main.innerHTML=october!==null?october:view==='artists'?artistsView():view==='artist'?artistProfile(route.split('/')[1]):view==='record'?detail(getRecord(route.split('/')[1])):view==='shelf'?shelf():view==='listening'?listening():view==='support'?support():discover();if($('#search'))$('#search').value=query;updateCollectionCount();updatePlayer();}
function source(){streaming=false;audio.src=current.audioFiles?.[side]?.[track]||`assets/${current.id}-${sideName(side).toLowerCase()}-${track+1}.${current.audioExt||'wav'}`;audio.load()}
async function resume(){if(typeof PortoOctober!=='undefined')PortoOctober.stopVoice();if(typeof PortoOctober!=='undefined'&&!PortoOctober.canPlay(current))return;const request=++playRequest;try{await audio.play();if(request!==playRequest)return;playing=true;updatePlayer()}catch{if(request!==playRequest)return;playing=false;streaming=false;toast('Audio could not start. Press play to try again.');updatePlayer()}}
function pause(){playRequest++;audio.pause();playing=false;streaming=false;updatePlayer()}
async function toggle(){if(playing)pause();else{if(audio.ended){track=0;source()}if(!audio.getAttribute('src'))source();await resume()}}
function lift(){pause();track=0;source();updatePlayer();if(location.hash==='#listening')render();toast('Needle lifted. This side is back at the beginning.')}
function playRecord(id,s){const r=getRecord(id);if(r.id!==current.id||s!==side){pause();current=r;side=s;track=0;source()}else if(!audio.getAttribute('src'))source();resume();location.hash='listening';render()}
function updatePlayer(){syncCollectionButtons();const live=playing&&streaming;$('#node-status').classList.toggle('is-live',live);$('#node-state').textContent=live?'LIVE':playing?'BUFFERING':audio.getAttribute('src')?'PAUSED':'READY';document.body.classList.toggle('playing',playing);$('#mini-cover').src=asset(current);$('#mini-title').textContent=current.tracks[side][track];$('#mini-artist').textContent=credited(current)?`Audio: ${creditList(current)[0].composer} · Side ${sideName(side)}`:`${current.artist} · Side ${sideName(side)}`;$('#play').innerHTML=playing?pauseIcon:playIcon;$('#play').setAttribute('aria-label',playing?'Pause playback':`Play side ${sideName(side)}`);$('#queue-count').textContent=queue.length?`Queue · ${queue.length}`:'Queue';$('#queue').setAttribute('aria-label',queue.length?`Open queue, ${queue.length} track${queue.length===1?'':'s'} waiting`:'Open queue, empty');$('#track-caption').textContent=playing?`Track ${track+1} of ${current.tracks[side].length}`:audio.ended?'Side complete':audio.currentTime>0?'Paused':'Ready to play';$('#player-mode').textContent=`SIDE ${sideName(side)} / ${isOwned(current)?'OWNED COPY':'ALBUM'}`;if($('#focus-play'))$('#focus-play').innerHTML=(playing?pauseIcon:playIcon)+(playing?' Pause':' Play');if($('#listening-state'))$('#listening-state').textContent=playing?'NOW PLAYING':'TAKE YOUR TIME';if($('#listening-title'))$('#listening-title').textContent=current.tracks[side][track];updateTime();if(typeof PortoOctober!=='undefined')PortoOctober.sync()}
function updateTime(){const total=sideDuration(current,side),elapsed=current.tracks[side].slice(0,track).reduce((sum,_,t)=>sum+duration(current,side,t),0)+(audio.currentTime||0);$('#elapsed').textContent=fmt(elapsed);$('#remaining').textContent=fmt(Math.max(0,total-elapsed));$('#progress-fill').style.width=Math.min(elapsed/total*100,100)+'%';$('.progress-track').setAttribute('aria-valuenow',Math.round(elapsed/total*100));if($('#seek')){$('#seek').max=duration(current,side,track);if(document.activeElement!==$('#seek'))$('#seek').value=audio.currentTime||0}}
function modal(html){resetWorldDialog();$('#dialog-content').innerHTML=html;$('#dialog').showModal()}
function about(){if(typeof PortoOctober!=='undefined'){PortoOctober.about();return;}modal(`<p class="eyebrow red">PORTO / CONCEPT 01</p><h2>A record-led listening room.</h2><p>Based on the pitch deck’s continuous listening and optional ownership concepts, using the Porto Design System 0.1.0-dev.1.</p><ul><li>Start a side and add tracks next.</li><li>Pause or lift the needle. Streaming has no scrubbing.</li><li>Explore vinyl first, or try a digital demo copy for seeking and downloads.</li></ul><p>The sleeves and original sound studies are demo material. Eleven releases use openly licensed recordings by Kevin MacLeod, with source and licence credits. The five artist editions add fifteen distinct full recordings. Genre labels describe fictional visual identities; the instrumental demo selections explore related moods. Artists, records and prices are fictional. No payments, licences, stream attestations or payouts are created. The LND-001 node indicator is simulated; audio is served from demo files.</p><a href="credits.html">Music credits & free downloads ↗</a><a class="primary" href="wireframe.html">Explore the wireframes ↗</a><button class="text-button" data-action="reset" style="margin-top:24px">Reset my demo shelf and purchases</button>`)}
function purchase(id,format='choose'){
 const r=getRecord(id);
 const record=`<div class="purchase-record"><img src="${asset(r)}" alt=""><div><h3>${r.title}</h3><small>${r.artist}</small></div></div>`;
 if(format==='vinyl'){modal(`<p class="eyebrow red">VINYL FIRST</p><h2>Buy the vinyl.</h2>${record}<p>The vinyl option leads to the artist or label’s record shop.</p><div class="format-demo-note"><strong>No vinyl shop connected</strong><p>This is a fictional release. There is no physical stock, order or checkout in this demo.</p></div><button class="secondary" data-action="buy-digital" data-id="${id}">Explore digital only</button>`);return}
 if(format==='digital'){modal(`<p class="eyebrow red">DIGITAL ONLY · DEMO</p><h2>A digital copy.</h2>${record}<p class="digital-price">£${r.price} <small>Illustrative price</small></p><ul><li>Seeking within tracks</li><li>A download of the credited demo audio</li><li>A place in your collection</li></ul><p>Demo only. Nothing is charged and no payment details are collected.</p>${isOwned(r)?`<a class="primary" href="assets/${r.id}-demo.zip" download>Download demo ↓</a>`:`<button class="primary coral" data-action="confirm-purchase" data-id="${id}">Try digital demo copy</button>`}<p class="legal-note">This does not include a physical record. Purchase licensing, fees and settlement remain to be defined.</p>`);return}
 modal(`<p class="eyebrow red">BUY THE RECORD</p><h2>Choose your copy.</h2>${record}${buyingOptions(r)}`);
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;
if(a==='open-sleeve'){openSleeveId=openSleeveId===id?null:id;sleevePane='back';render();const target=openSleeveId?$('#open-jacket'):document.querySelector(`[data-action="open-sleeve"][data-id="${id}"]`);target?.focus({preventScroll:true});if(openSleeveId)target?.scrollIntoView({block:'start',behavior:'instant'})}
if(a==='close-sleeve'){const previous=openSleeveId;openSleeveId=null;render();document.querySelector(`[data-action="open-sleeve"][data-id="${previous}"]`)?.focus({preventScroll:true})}
if(a==='sleeve-pane'){sleevePane=b.dataset.pane;const r=getRecord(openSleeveId);$('#jacket-leaf').innerHTML=sleevePane==='notes'?sleeveNotes(r):sleeveBack(r);document.querySelectorAll('[data-action="sleeve-pane"]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.pane===sleevePane)))}
if(a==='save')toggleCollection(id);if(a==='filter'){filter=b.dataset.filter;render()}if(a==='shelf-filter'){shelfFilter=b.dataset.filter;render()}if(a==='side'){selectedSide=+b.dataset.side;render()}if(a==='play-record')playRecord(id,+b.dataset.side);if(a==='toggle')toggle();if(a==='lift')lift();if(a==='flip'){pause();side=1-side;track=0;source();render();toast(`Side ${sideName(side)} is ready. Drop the needle when you are.`)}if(a==='purchase')purchase(id);if(a==='buy-vinyl')purchase(id,'vinyl');if(a==='buy-digital')purchase(id,'digital');if(a==='confirm-purchase'){if(!owned.includes(id))owned.push(id);const persisted=persist();$('#dialog').close();render();toast(persisted?'Demo copy added. Seeking and downloads are unlocked.':'Demo copy added for this visit only. Browser storage is unavailable.')}if(a==='queue')queueTrack(id,+b.dataset.side,+b.dataset.track);if(a==='remove-queue'){queue.splice(+b.dataset.index,1);queueDialog();updatePlayer()}if(a==='reset'){saved=[...starterShelf];owned=[];const persisted=persist();$('#dialog').close();render();toast(persisted?'Demo collection restored. Purchases reset.':'Collection reset for this visit only. Browser storage is unavailable.')}});
document.addEventListener('change',e=>{if(e.target.id==='genre-filter'){filter=e.target.value;$('#catalog').innerHTML=catalogResults()}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;$('#catalog').innerHTML=catalogResults();}if(e.target.id==='seek'&&isOwned(current)){audio.currentTime=+e.target.value;updateTime()}});
$('#queue').addEventListener('click',queueDialog);$('#play').addEventListener('click',toggle);$('#lift').addEventListener('click',lift);$('#player-record').addEventListener('click',()=>{location.hash='listening'});$('#volume').addEventListener('input',e=>audio.volume=+e.target.value);$('#about-button').addEventListener('click',about);$('#profile-button').addEventListener('click',about);$('.dialog-close').addEventListener('click',()=>$('#dialog').close());$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
audio.autoplay=false;audio.removeAttribute('autoplay');audio.volume=.65;audio.addEventListener('timeupdate',updateTime);audio.addEventListener('play',()=>{playing=true;updatePlayer()});audio.addEventListener('playing',()=>{streaming=true;playing=true;updatePlayer()});for(const event of ['waiting','stalled','loadstart'])audio.addEventListener(event,()=>{streaming=false;updatePlayer()});audio.addEventListener('pause',()=>{streaming=false;playing=false;updatePlayer()});audio.addEventListener('error',()=>{streaming=false;playing=false;updatePlayer();toast('The demo audio could not load. Please try again.')});audio.addEventListener('ended',()=>{streaming=false;if(playQueuedTrack()){if(location.hash==='#listening'||location.hash.startsWith('#record/'))render()}else if(track<current.tracks[side].length-1){track++;source();resume();if(location.hash==='#listening'||location.hash.startsWith('#record/'))render()}else{playing=false;updatePlayer();toast(current.concept?'Demo preview finished. Refine it or share your version.':`Side ${sideName(side)} has finished. Turn the record over when you are ready.`);if(location.hash==='#listening')render()}});
window.addEventListener('storage',e=>{if(e.key===null||['porto-saved','porto-owned'].includes(e.key)){saved=readCollectionIds('porto-saved');owned=readCollectionIds('porto-owned');render()}});
window.addEventListener('hashchange',()=>{const menu=document.querySelector('.nav-more');if(menu)menu.open=false;if($('#dialog').open)$('#dialog').close();selectedSide=0;render();window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true})});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&openSleeveId&&!$('#dialog').open){const previous=openSleeveId;openSleeveId=null;render();document.querySelector(`[data-action="open-sleeve"][data-id="${previous}"]`)?.focus({preventScroll:true});return}if(e.code==='Space'&&!['INPUT','BUTTON','A','TEXTAREA','SELECT','SUMMARY'].includes(e.target.tagName)&&!$('#dialog').open){e.preventDefault();toggle()}});bindArtistEvents();render();if(typeof PortoOctober!=='undefined')PortoOctober.init();
